import json,html,re,shutil
from pathlib import Path
P=Path(__file__).parent
OUT=P.parent
D=json.loads((OUT/'oled-market-data.json').read_text())
for m in D['models']:
 n=m['name'];m['brand']=next((en for zh,en in [('華碩','ASUS'),('技嘉','GIGABYTE'),('三星','Samsung'),('微星','MSI')] if zh in n),n.split(' ')[0])
E=lambda x:html.escape(str(x),quote=True)
money=lambda n:f'NT${n:,}'
def link(url,label):return f'<a href="{E(url)}" target="_blank" rel="noopener noreferrer">{E(label)} ↗</a>'
def price(s):
 if not s:return '<span class="muted">未找到列售</span>'
 return link(s['url'],money(s['price']))+f'<small class="{ "warn" if s["status"]=="補貨中" else "muted"}">{E(s["status"])}'+(' · 組合價' if s.get('bundle') else '')+'</small>'
rows=[]
for i,m in enumerate(D['models']):
 m['key']='m'+str(i+1)
 reviews=[next(r for r in D['reviews'] if r['id']==rid) for rid in m['reviews']]
 forum=''.join(f'<a class="reviewlink" href="#{r["id"]}">{E(r["kind"])} · {E(r["title"])}</a>' for r in reviews) or '<span class="muted">尚無精選同型號文章；不代表無災情。</span>'
 details=''.join('<p>'+E(n)+'</p>' for n in m['notes'])
 if m['official']:details+='<p>'+link(m['official'],'產品／原廠資料')+'</p>'
 if m['sinya']:details+='<h4>欣亞各商品頁</h4>'+''.join('<p>'+price(s)+'<small>'+E(s['name'])+'</small></p>' for s in m['sinya'])
 details+=f'<h4>論壇紀錄</h4>{forum}'
 genlink=link(m['generation_source'],'世代依據') if m['generation_source'] else '未取得可靠的同型號代數依據'
 tags=('曲面 · ' if m['curved'] else '')+('專業用途 · ' if m['professional'] else '')+('僅補貨中' if not m['available'] else '')
 rows.append(f'''<tr id="{m['key']}" data-key="{m['key']}"><th scope="row"><small>{E(m['name'].split(' ')[0])}</small><strong>{E(m['model'])}</strong><small class="warn">{E(tags)}</small><details><summary>來源、通路與心得（{len(reviews)}）</summary><div>{details}</div></details></th><td data-label="規格"><b>{m['size']} 吋級 · {m['resolution']}</b><small>{m['hz']}Hz{(' ／ '+E(m['dual'])) if m.get('dual') else ''}</small><small>{E(m['panel'])}</small></td><td data-label="OLED 世代"><b>{E(m['generation'])}</b><small>{E(m['gen_status'])}</small><small>{genlink}</small></td><td data-label="原價屋">{price(m['coolpc'])}</td><td data-label="欣亞">{price(m['sinya_best'])}</td></tr>''')
reviews=[]
for r in D['reviews']:
 models=''.join(f'<button class="modeljump" data-model="{E(n)}">{E(n)}</button>' for n in r['models'])
 reviews.append(f'''<article class="review" id="{r['id']}" data-kind="{E(r['kind'])}"><div class="eyebrow">{r['id']} / {'PTT' if 'ptt.cc' in r['url'] else '巴哈姆特'} / {E(r['kind'])}</div><h3>{link(r['url'],r['title'])}</h3><small>{E(r['date'])}</small><p>{E(r['summary'])}</p><p class="limit">判讀：{E(r['limit'])}</p><div>{models}</div></article>''')
cards=[]
for name,tag,why in [
 ('XG27UQDMS','27 吋 4K｜我的起點','約 2 萬元就有 4K 240Hz、第 4 代 QD-OLED；適合只接桌機。無 USB-C 影像。'),
 ('MPG 321URX QD-OLED','32 吋 4K｜大畫面實惠選','原價屋 20,888 元，4K 240Hz、第 3 代 QD-OLED。不用為 32 吋直接把預算拉到 4 萬。'),
 ('MO27Q28G','27 吋 QHD｜較亮房間的候選','11,990 元、第 4 代 Tandem WOLED，霧面 280Hz。想要鏡面，可比較 14,990 元的 GR。'),
 ('MAG 272QP QD-OLED X50','27 吋 QHD｜競技優先','16,900 元、500Hz、第 3 代 QD-OLED。前提是常玩的遊戲能輸出足夠高幀率。'),
 ('MPG 272URX QD-OLED','27 吋 4K｜需要完整接口','24,888 元、第 4 代 QD-OLED；USB-C 98W、KVM、DP 2.1 UHBR20。先讀表面異常回報。'),
 ('PG27UCWM','27／32 吋 4K｜確定要攻頂','27 吋 34,888、32 吋 37,888 元。Tandem RGB Stripe、4K 240Hz／FHD 480Hz；官方未給數字世代。')]:
  m=next(x for x in D['models'] if x['model']==name)
  cards.append(f'<article class="pick"><div class="eyebrow">{E(tag)}</div><h3>{E(name)}</h3><p>{E(why)}</p><button data-model="{E(name)}">查看兩家售價與心得 →</button></article>')
